153	// ============================================================================
154	// VM — page-table walk (the CP DMA is an MMU-aware copy engine)
155	// ============================================================================
156	
157	uint64_t CommandProcessor::cp_translate(uint64_t vaddr, bool physical) const {
158	#ifdef VX_CFG_VM_ENABLE
159	    if (physical || satp_ == 0)
160	        return vaddr;
161	    SATP_t satp(satp_);
162	    if (satp.get_mode() == BARE)
163	        return vaddr;
164	    // Sv32/Sv39 walk — mirrors VMManager::page_table_walk so the CP DMA and
165	    // the host driver resolve addresses identically.
166	    int i = VX_VM_PT_LEVEL - 1;
167	    vAddr_t va(vaddr);
168	    uint64_t cur_base_ppn = satp.get_base_ppn();
169	    for (;;) {
170	        uint64_t pte_addr  = cur_base_ppn * VX_VM_PT_SIZE
171	                           + va.vpn[i] * VX_VM_PTE_SIZE;
172	        uint64_t pte_bytes = 0;
173	        if (hooks_.dram_read)
174	            hooks_.dram_read(pte_addr, &pte_bytes, VX_VM_PTE_SIZE);
175	        PTE_t pte(pte_bytes);
176	        if (pte.v == 0)
177	            return vaddr;            // unmapped — pass through (defensive)
178	        if (pte.r == 0 && pte.w == 0 && pte.x == 0) {
179	            if (--i < 0)
180	                return vaddr;        // no leaf — pass through
181	            cur_base_ppn = pte.ppn;
182	            continue;
183	        }
184	        cur_base_ppn = pte.ppn;      // leaf found at level i
185	        break;
186	    }
187	    // Reconstruct the physical address. For a leaf found at level i > 0 (a
188	    // mega/gigapage) the low VX_VM_PAGE_LOG2_SIZE + i*VPN_BITS address bits
189	    // are the offset *within* the superpage and must come from the VA, not
190	    // from the (superpage-aligned) leaf PPN. For a 4 KB leaf (i == 0) this
191	    // reduces to the ordinary ppn<<12 | page-offset.
192	    constexpr unsigned VPN_BITS = cp_clog2(VX_VM_PT_SIZE / VX_VM_PTE_SIZE);
193	    const uint64_t off_mask =
194	        (uint64_t(1) << (VX_VM_PAGE_LOG2_SIZE + i * VPN_BITS)) - 1;
195	    return ((cur_base_ppn << VX_VM_PAGE_LOG2_SIZE) & ~off_mask)
196	         | (vaddr & off_mask);
197	#else
198	    (void)physical;
199	    return vaddr;
200	#endif
201	}
