457	vx_result_t Device::cp_submit_dcr_write(uint32_t addr, uint32_t value) {
458	    // VM safety check: when VM is active and the pinned slab is configured,
459	    // every HW-addr DCR must reference a buffer in the pinned slab — the HW
460	    // master bypasses the per-core MMU and would otherwise dereference a stale VA.
461	    //
462	    // TEX / RASTER / OM address DCRs encode value as a cache-block index
463	    // (pa = value << 6). Split BASE_LO/HI DCR pairs (e.g. DXA) are validated
464	    // by the caller, not here.
465	    if (vm_enabled_ && pinned_mem_) {
466	        switch (addr) {
467	        case VX_DCR_TEX_ADDR:
468	        case VX_DCR_RASTER_TBUF_ADDR:
469	        case VX_DCR_RASTER_PBUF_ADDR:
470	        case VX_DCR_OM_CBUF_ADDR:
471	        case VX_DCR_OM_ZBUF_ADDR: {
472	            const uint64_t pa = uint64_t(value) << 6;
473	            if (pa < pinned_base_ ||
474	                pa >= pinned_base_ + pinned_size_) {
475	                std::cerr << "[VXDRV] dcr 0x" << std::hex << addr
476	                          << " value 0x" << value << " (pa 0x" << pa
477	                          << ") not in pinned slab [0x" << pinned_base_
478	                          << ", 0x" << (pinned_base_ + pinned_size_)
479	                          << ") — buffer needs VX_MEM_PHYS"
480	                          << std::dec << std::endl;
481	                return VX_ERR_INVALID_VALUE;
482	            }
483	            break;
484	        }
485	        default:
486	            break;
487	        }
488	    }
489	    // CMD_DCR_WRITE on-wire layout (cmd_size=20):
490	    //   bytes 0..3   header  { opcode=0x04, flags=0, reserved=0 }
491	    //   bytes 4..11  arg0    DCR addr
492	    //   bytes 12..19 arg1    DCR value
493	    // Rest of CL is padded with zeros (NOP sentinel for the unpacker).
494	    uint8_t cl[CP_CL_BYTES] = {0};
495	    uint32_t* p32 = reinterpret_cast<uint32_t*>(cl);
496	    p32[0] = CP_OPCODE_DCR_WR;
497	    p32[1] = addr;
498	    p32[3] = value;
499	    return cp_submit_cl_(cl);
500	}
