533	    auto r = cp_submit_cl_(cl);
534	    if (r != VX_SUCCESS) return r;
535	    r = cp_submit_cache_flush();
536	    if (r != VX_SUCCESS) return r;
537	    if (cp_in_batch_) return VX_SUCCESS;
538	    return drain_cout();
539	}
