232	vx_result_t Device::cp_init() {
233	    // Ring + head + completion live in CP-visible host memory: the runtime
234	    // appends commands straight through the ring's host pointer and the CP
235	    // fetches them over its m_axi_host master — no per-command DMA.
236	    auto* p = platform();
237	    auto r = host_alloc(CP_RING_SIZE, &cp_ring_);
238	    if (r != VX_SUCCESS) return r;
239	    r = host_alloc(CP_CL_BYTES, &cp_head_);
240	    if (r != VX_SUCCESS) return r;
241	    r = host_alloc(CP_CL_BYTES, &cp_cmpl_);
242	    if (r != VX_SUCCESS) return r;
243	
244	    // Zero them so the CP doesn't read stale data on first fetch.
245	    std::memset(cp_ring_.host_ptr, 0, CP_RING_SIZE);
246	    std::memset(cp_head_.host_ptr, 0, CP_CL_BYTES);
247	    std::memset(cp_cmpl_.host_ptr, 0, CP_CL_BYTES);
248	
249	    // Program CP queue 0. Any failure here is fatal — the CP regfile is
250	    // the sole control path, so a botched setup means cp_enabled_=true
251	    // would lie about a working device. Macro keeps the call list legible.
252	    #define CP_WR(_off, _val) do {                                          \
253	        auto _r = p->cp_reg_write((_off), (_val));                          \
254	        if (_r != VX_SUCCESS) return _r;                                    \
255	    } while (0)
256	    CP_WR(CP_Q_RING_BASE_LO,   uint32_t(cp_ring_.cp_addr & 0xFFFFFFFFu));
257	    CP_WR(CP_Q_RING_BASE_HI,   uint32_t(cp_ring_.cp_addr >> 32));
